// Generates party-guest.js (PartyBox guest page) for Windows and Android from design/party-guest.html
import fs from 'node:fs';
const root = new URL('..', import.meta.url).pathname;
const html = fs.readFileSync(root + 'design/party-guest.html', 'utf8');
const js = `'use strict';
/* Generated by tools/gen-party.mjs — edit design/party-guest.html */
const PARTY_GUEST_TPL = ${JSON.stringify(html)};
function partyGuestPage({ ended }) {
  const lang = typeof I18N !== 'undefined' ? I18N.lang : 'en';
  const cfg = JSON.stringify({ ended: !!ended, title: partyName(), lang }).replace(/</g, '\\\\u003c');
  return PARTY_GUEST_TPL.replace('__LANG__', lang).replace('__TITLE__', () => esc(partyName())).replace('__CFG__', () => cfg);
}
`;
for (const d of ['app-windows/renderer/', 'app-android/src/']) fs.writeFileSync(root + d + 'party-guest.js', js);
console.log('party-guest.js generated');
